let firebaseUid=null;let db=load();if(!['en','hi','pa','mr','ta'].includes(db.language))db.language='en';db.loggedIn=false;let view='landing',selectedMachine=null,workflow={kind:'',step:0,machine:'',audio:null,vibration:null},recordTimer=null,recordStream=null,audioRecorder=null,audioChunks=[],motionHandler=null,notifOpen=false,authMode='login',pendingRoute='';
function normalizeStore(d){if(!d)return structuredClone(seed);let normalized={...structuredClone(seed),...d,machines:d.machines?.length?d.machines:structuredClone(seed.machines)};if(!d.mlPipelineVersion){normalized.healthTests=(d.healthTests||[]).map(row=>({...row,modelScope:row.modelScope||'Legacy demo prediction — not model output'}));normalized.leakScans=(d.leakScans||[]).map(row=>({...row,modelScope:row.modelScope||'Legacy demo scan — not model output'}));normalized.machines=normalized.machines.map(machine=>({...machine,health:null,state:['Attention','Possible fault','Possible Fault'].includes(machine.state)?'Running':machine.state,reason:undefined}));normalized.alerts=normalized.alerts.filter(alert=>!['seed-health','seed-leak'].includes(alert.id));normalized.mlPipelineVersion=1}return normalized}
function load(){try{return normalizeStore(JSON.parse(localStorage.getItem(STORE)))}catch{return structuredClone(seed)}}
function loadForUser(uid){try{return normalizeStore(JSON.parse(localStorage.getItem(`${STORE}:${uid}`)))}catch{return structuredClone(seed)}}
function save(){localStorage.setItem(firebaseUid?`${STORE}:${firebaseUid}`:STORE,JSON.stringify(db))}
const translations={en:{Overview:'Overview',Machines:'Machines',Monitor:'Monitor',Alerts:'Alerts',Reports:'Reports',Settings:'Settings',Welcome:'Factory monitoring overview',CurrentDemand:'Current demand',TodaysEnergy:"Today’s energy",MachineHealth:'Machine health',ActiveAlerts:'Active alerts',ViewMachines:'View machines',StartCheck:'Start check',ViewIdle:'View idle machines',ViewDemand:'View demand',Explore:'Explore demo',Login:'Login',Connected:'Connected',Running:'Running',Idle:'Idle',Attention:'Attention',Fault:'Possible fault',StartRecording:'Start recording',Continue:'Continue',Back:'Back',Generate:'Generate report'},hi:{Overview:'अवलोकन',Machines:'मशीनें',Monitor:'निगरानी',Alerts:'सूचनाएँ',Reports:'रिपोर्ट',Settings:'सेटिंग्स',Welcome:'फैक्टरी निगरानी अवलोकन',CurrentDemand:'वर्तमान मांग',TodaysEnergy:'आज की ऊर्जा',MachineHealth:'मशीन स्वास्थ्य',ActiveAlerts:'सक्रिय सूचनाएँ',ViewMachines:'मशीनें देखें',StartCheck:'जाँच शुरू करें',ViewIdle:'निष्क्रिय मशीनें',ViewDemand:'मांग देखें',Explore:'डेमो देखें',Login:'लॉगिन',Connected:'जुड़ा हुआ',Running:'चालू',Idle:'निष्क्रिय',Attention:'ध्यान दें',Fault:'संभावित खराबी',StartRecording:'रिकॉर्डिंग शुरू करें',Continue:'आगे बढ़ें',Back:'वापस',Generate:'रिपोर्ट बनाएँ'},pa:{Overview:'ਸੰਖੇਪ',Machines:'ਮਸ਼ੀਨਾਂ',Monitor:'ਨਿਗਰਾਨੀ',Alerts:'ਸੂਚਨਾਵਾਂ',Reports:'ਰਿਪੋਰਟਾਂ',Settings:'ਸੈਟਿੰਗਾਂ',Welcome:'ਫੈਕਟਰੀ ਨਿਗਰਾਨੀ ਸੰਖੇਪ',CurrentDemand:'ਮੌਜੂਦਾ ਮੰਗ',TodaysEnergy:'ਅੱਜ ਦੀ ਊਰਜਾ',MachineHealth:'ਮਸ਼ੀਨ ਸਿਹਤ',ActiveAlerts:'ਸਰਗਰਮ ਸੂਚਨਾਵਾਂ',ViewMachines:'ਮਸ਼ੀਨਾਂ ਵੇਖੋ',StartCheck:'ਜਾਂਚ ਸ਼ੁਰੂ ਕਰੋ',ViewIdle:'ਨਿਸ਼ਕ੍ਰਿਆ ਮਸ਼ੀਨਾਂ',ViewDemand:'ਮੰਗ ਵੇਖੋ',Explore:'ਡੈਮੋ ਵੇਖੋ',Login:'ਲੌਗ ਇਨ',Connected:'ਜੁੜਿਆ',Running:'ਚੱਲ ਰਿਹਾ',Idle:'ਨਿਸ਼ਕ੍ਰਿਆ',Attention:'ਧਿਆਨ',Fault:'ਸੰਭਾਵੀ ਖ਼ਰਾਬੀ',StartRecording:'ਰਿਕਾਰਡਿੰਗ ਸ਼ੁਰੂ',Continue:'ਜਾਰੀ ਰੱਖੋ',Back:'ਵਾਪਸ',Generate:'ਰਿਪੋਰਟ ਬਣਾਓ'},mr:{Overview:'आढावा',Machines:'मशीन',Monitor:'देखरेख',Alerts:'सूचना',Reports:'अहवाल',Settings:'सेटिंग्ज',Welcome:'कारखाना देखरेख आढावा',CurrentDemand:'सध्याची मागणी',TodaysEnergy:'आजची ऊर्जा',MachineHealth:'मशीन आरोग्य',ActiveAlerts:'सक्रिय सूचना',ViewMachines:'मशीन पहा',StartCheck:'तपासणी सुरू करा',ViewIdle:'निष्क्रिय मशीन',ViewDemand:'मागणी पहा',Explore:'डेमो पहा',Login:'लॉगिन',Connected:'जोडलेले',Running:'चालू',Idle:'निष्क्रिय',Attention:'लक्ष द्या',Fault:'संभाव्य बिघाड',StartRecording:'रेकॉर्डिंग सुरू करा',Continue:'पुढे',Back:'मागे',Generate:'अहवाल तयार करा'},ta:{Overview:'கண்ணோட்டம்',Machines:'இயந்திரங்கள்',Monitor:'கண்காணிப்பு',Alerts:'எச்சரிக்கைகள்',Reports:'அறிக்கைகள்',Settings:'அமைப்புகள்',Welcome:'தொழிற்சாலை கண்காணிப்பு கண்ணோட்டம்',CurrentDemand:'தற்போதைய தேவை',TodaysEnergy:'இன்றைய ஆற்றல்',MachineHealth:'இயந்திர நலம்',ActiveAlerts:'செயலில் உள்ள எச்சரிக்கைகள்',ViewMachines:'இயந்திரங்களைக் காண்க',StartCheck:'சோதனையைத் தொடங்கு',ViewIdle:'செயலற்ற இயந்திரங்கள்',ViewDemand:'தேவையைக் காண்க',Explore:'டெமோவைப் பார்க்கவும்',Login:'உள்நுழை',Connected:'இணைக்கப்பட்டது',Running:'இயக்கம்',Idle:'செயலற்றது',Attention:'கவனம்',Fault:'சாத்தியமான கோளாறு',StartRecording:'பதிவைத் தொடங்கு',Continue:'தொடர்க',Back:'பின்',Generate:'அறிக்கையை உருவாக்கு'},gu:{},bn:{},kn:{}};
function t(k){return translations[db.language]?.[k]||translations.en[k]||k}const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function mlApiUrl(path){const base=(window.URJA_ML_API_URL||'').replace(/\/$/,'');return `${base}${path}`}
function timeNow(){return new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}function dateNow(){return new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}
function demand(){return Math.round((db.machines.reduce((a,m)=>a+m.power,0)+(db.auxiliaryLoad||0))*10)/10}function countRealChecks(){return db.healthTests.filter(row=>!String(row.modelScope||'').startsWith('Legacy demo')).length}function healthCounts(){let c={healthy:0,attention:0,fault:0};db.machines.forEach(m=>{if(!Number.isFinite(m.health))return;if(m.health>=80)c.healthy++;else if(m.health>=60)c.attention++;else c.fault++});return c}
function badge(state){let cl=state==='Attention'?'warn':state==='Possible fault'||state==='Fault'?'bad':state==='Idle'?'warn':state==='Resolved'?'neutral':'';return `<span class="status ${cl}">${esc(t(state))}</span>`}
function icon(name){return ({Overview:'◫',Machines:'▦',Monitor:'◉',Alerts:'♧',Reports:'▤',Settings:'⚙'})[name]||'•'}
function nav(){const items=['Overview','Machines','Monitor','Alerts','Reports','Settings'];return `<aside class="sidebar"><div class="brand"><div class="brand-mark">U</div><div class="brand-name">UrjaDrishti<small>FACTORY INTELLIGENCE</small></div></div><div class="nav-label">WORKSPACE</div><nav class="nav-list">${items.map(n=>`<a href="#${n.toLowerCase()}" class="nav-link ${view===n.toLowerCase()?'active':''}" onclick="go('${n.toLowerCase()}');return false"><span class="nav-ico">${icon(n)}</span>${t(n)}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="factory-switch">YOUR FACTORY<strong>⌂ &nbsp;${esc(db.factory)}</strong>${esc(db.location)}</div><div class="side-user"><div class="avatar">A</div><div>Factory Admin<small>Owner account</small></div></div></div></aside>`}
function shell(body){return `<div class="app-shell">${nav()}<main class="main-area"><header class="topbar"><div class="crumb"><strong>${esc(t(labelForView()))}</strong> &nbsp;›&nbsp; ${esc(db.factory)}</div><div class="mobile-top"><div class="brand-mark">U</div><div class="brand-name">UrjaDrishti</div></div><div class="top-actions"><select class="lang-select" aria-label="Language" onchange="setLang(this.value)"><option value="en" ${db.language==='en'?'selected':''}>English</option><option value="hi" ${db.language==='hi'?'selected':''}>हिन्दी</option><option value="pa" ${db.language==='pa'?'selected':''}>ਪੰਜਾਬੀ</option><option value="mr" ${db.language==='mr'?'selected':''}>मराठी</option><option value="ta" ${db.language==='ta'?'selected':''}>தமிழ்</option><option value="gu" ${db.language==='gu'?'selected':''}>ગુજરાતી</option><option value="bn" ${db.language==='bn'?'selected':''}>বাংলা</option><option value="kn" ${db.language==='kn'?'selected':''}>ಕನ್ನಡ</option></select><button class="icon-btn" onclick="go('alerts')" aria-label="Notifications">♧${db.alerts.some(a=>!a.read)?'<i class="notif-dot"></i>':''}</button><div class="avatar">A</div></div></header><section class="content">${body}</section><nav class="bottom-nav">${[['overview','◫','Overview'],['machines','▦','Machines'],['monitor','◉','Monitor'],['alerts','♧','Alerts'],['settings','⚙','Settings']].map(([v,i,l])=>`<a href="#${v}" onclick="go('${v}');return false" class="${view===v?'active':''}"><span>${i}</span>${t(l)}</a>`).join('')}</nav></main></div>`}
function labelForView(){return ({overview:'Overview',machines:'Machines',monitor:'Monitor',alerts:'Alerts',reports:'Reports',settings:'Settings',machine:'Machines',health:'Machine Health',leak:'Air Leak Detection',idle:'Idle Monitoring',demand:'Peak Demand'})[view]||'Overview'}
function pageHead(title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${esc(db.factory)} &nbsp;·&nbsp; ${dateNow()}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function chart(values= [24,29,25,43,38,52,47,70,62,81,74,91],id='chart'){let w=700,h=200,L=38,R=8,T=12,B=25,innerW=w-L-R,innerH=h-T-B,max=Math.max(...values)*1.18,min=0;let pts=values.map((v,i)=>[L+i*innerW/(values.length-1),T+innerH-(v-min)/(max-min)*innerH]);let path=pts.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' '),area=`${path} L${pts.at(-1)[0]},${h-B} L${L},${h-B} Z`;return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Today's electricity trend"><defs><linearGradient id="${id}-g" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#92b58b" stop-opacity=".3"/><stop offset="100%" stop-color="#92b58b" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{let y=T+i*innerH/3;return `<line class="chart-grid" x1="${L}" y1="${y}" x2="${w-R}" y2="${y}"/><text class="chart-label" x="0" y="${y+3}">${Math.round(max*(3-i)/3)}</text>`}).join('')}<path d="${area}" fill="url(#${id}-g)"/><path class="chart-line" d="${path}"/>${pts.filter((_,i)=>i===pts.length-1).map(p=>`<circle class="chart-point" cx="${p[0]}" cy="${p[1]}" r="4"/>`).join('')}<text class="chart-label" x="${L}" y="${h-4}">08:00</text><text class="chart-label" x="${w/2}" y="${h-4}" text-anchor="middle">12:00</text><text class="chart-label" x="${w-R}" y="${h-4}" text-anchor="end">16:00</text></svg></div>`}
function machineRows(list=db.machines){return list.map(m=>`<tr onclick="openMachine('${m.id}')" style="cursor:pointer"><td><div class="machine-name">${esc(m.name)}</div><div class="machine-id">${m.id}</div></td><td>${badge(m.state)}</td><td>${m.power.toFixed(1)} kW</td><td><strong>${m.health}</strong></td><td>${m.idle?`${m.idleMinutes||20} min`:'—'}</td><td>${m.last}</td></tr>`).join('')}
function alertsForView(){return db.alerts.filter(a=>!a.resolved).slice(0,4)}
function dashboard(){let c=healthCounts(),d=demand(),active=db.alerts.filter(a=>!a.resolved).length,idles=db.machines.filter(m=>m.idle),lastLeak=db.leakScans.find(row=>!row.modelScope?.startsWith('Legacy demo'));return `${pageHead(t('Welcome'),`Good morning, Admin. &nbsp; Last updated ${timeNow()}.`,`<button class="button secondary" onclick="go('reports')">▤ &nbsp; ${t('Generate')}</button>`)}<div class="cards summary-grid"><article class="card stat-card"><div class="stat-head">${t('CurrentDemand')}<span class="stat-icon">ϟ</span></div><div class="stat-value">${d.toFixed(1)} <small style="font:500 12px 'DM Sans';color:var(--muted)">kW</small></div><div class="stat-foot ${d<db.limit?'good':'bad'}">${d<db.limit?`${(db.limit-d).toFixed(1)} kW available`:`${(d-db.limit).toFixed(1)} kW over limit`}</div></article><article class="card stat-card"><div class="stat-head">${t('TodaysEnergy')}<span class="stat-icon">▥</span></div><div class="stat-value">1,248 <small style="font:500 12px 'DM Sans';color:var(--muted)">kWh</small></div><div class="stat-foot">Across ${db.machines.length} monitored machines</div></article><article class="card stat-card"><div class="stat-head">${t('MachineHealth')}<span class="stat-icon">⌁</span></div><div class="stat-value">${c.healthy} <small style="font:500 12px 'DM Sans';color:var(--muted)">healthy</small></div><div class="stat-foot">${c.attention} attention · ${c.fault} possible fault</div></article><article class="card stat-card"><div class="stat-head">${t('ActiveAlerts')}<span class="stat-icon">♧</span></div><div class="stat-value">${active}</div><div class="stat-foot">${db.alerts.length-active} resolved today</div></article></div><div class="cards feature-grid"><article class="card feature-card"><div class="feature-title"><span class="feature-mark">⌁</span>Machine Health</div><div class="feature-metric">Today's checks</div><div class="feature-value">${countRealChecks()} tested · ${c.fault} issue</div><div class="feature-foot"><span class="subtle">Sound + vibration</span><button class="button soft" onclick="startWorkflow('health')">${t('StartCheck')} →</button></div></article><article class="card feature-card"><div class="feature-title"><span class="feature-mark">◖</span>Air Leak Detection</div><div class="feature-metric">${lastLeak?`Last scan · ${esc(lastLeak.time)}`:'No scans yet'}</div><div class="feature-value">${lastLeak?(lastLeak.leak?'Abnormal sound flagged':'No abnormal sound flagged'):'No scan recorded'}</div><div class="feature-foot"><span class="subtle">Microphone scan</span><button class="button soft" onclick="startWorkflow('leak')">Scan →</button></div></article><article class="card feature-card"><div class="feature-title"><span class="feature-mark">◴</span>Idle Monitoring</div><div class="feature-metric">Automatically monitored</div><div class="feature-value">${idles.length} ${idles.length===1?'machine':'machines'} idle</div><div class="feature-foot"><span class="subtle">${idles[0]?`${idles[0].name} — ${idles[0].idleMinutes} min`:'No idle machines'}</span><button class="button soft" onclick="go('idle')">${t('ViewIdle')} →</button></div></article><article class="card feature-card"><div class="feature-title"><span class="feature-mark">ϟ</span>Peak Demand</div><div class="feature-metric">Current / allowed</div><div class="feature-value">${d.toFixed(1)} / ${db.limit} kW</div><div class="feature-foot"><span class="subtle">${d>db.limit?'Limit exceeded':'Within limit'}</span><button class="button soft" onclick="go('demand')">${t('ViewDemand')} →</button></div></article></div><div class="dashboard-grid"><article class="card panel"><div class="panel-head"><div><div class="panel-title">Machine overview</div><div class="panel-subtitle">Live readings · updates every 10 minutes</div></div><div class="live-pill"><i class="live-dot"></i> ${t('Connected').toUpperCase()}</div></div><div class="table-wrap"><table class="machine-table"><thead><tr><th>MACHINE</th><th>STATUS</th><th>POWER</th><th>HEALTH</th><th>IDLE</th><th>LAST CHECKED</th></tr></thead><tbody>${machineRows(db.machines.slice(0,5))}</tbody></table></div><button class="link-button" onclick="go('machines')">All machines →</button></article><div><article class="demand-card"><div class="demand-head">MAXIMUM ALLOWED DEMAND</div><div class="demand-main"><strong>${d.toFixed(1)}</strong><span> / ${db.limit} kW</span></div><div class="demand-meter"><div class="demand-fill" style="width:${Math.min(100,d/db.limit*100)}%"></div></div><div class="demand-foot"><span>${d>db.limit?'LIMIT EXCEEDED':'NORMAL'}</span><span>${d>db.limit?`${(d-db.limit).toFixed(1)} kW over`:`${(db.limit-d).toFixed(1)} kW available`}</span></div></article><article class="card panel"><div class="panel-head"><div><div class="panel-title">Recent alerts</div><div class="panel-subtitle">Events that may need attention</div></div><button class="link-button" onclick="go('alerts')">All →</button></div>${alertList(alertsForView())}</article></div></div><div class="section"><article class="card panel"><div class="panel-head"><div><div class="panel-title">Today's factory demand</div><div class="panel-subtitle">Simulated meter readings · kW</div></div><div class="legend"><span><i></i>Demand</span><span>Limit ${db.limit} kW</span></div></div>${chart()}</article></div>`}
function alertList(list){if(!list.length)return `<div class="empty-state"><strong>You're all caught up</strong>No active alerts right now.</div>`;return `<div class="alert-list">${list.map(a=>`<div class="alert-item"><div class="alert-icon">${a.type==='Peak Demand'?'ϟ':a.type==='Air Leak'?'◖':a.type==='Idle'?'◴':'⌁'}</div><div><div class="alert-text">${esc(a.title)}</div><div class="alert-meta">${esc(a.message)} · ${esc(a.time)}</div></div>${badge(a.resolved?'Resolved':a.severity==='critical'?'Possible fault':a.severity==='warning'?'Attention':'Running')}</div>`).join('')}</div>`}
function machinesPage(){return `${pageHead('Machines',`${db.machines.length} machines · Select a machine to view its readings and checks.`,`<button class="button" onclick="addMachine()">＋ &nbsp; Add machine</button>`)}<div class="cards machine-grid">${db.machines.map(m=>`<article class="card machine-card" onclick="openMachine('${m.id}')"><div class="machine-card-head"><div><h3>${esc(m.name)}</h3><div class="machine-id">${m.id} · ${esc(m.type)}</div></div>${badge(m.state)}</div><div class="machine-metrics"><div class="machine-metric"><label>Current power</label><strong>${m.power.toFixed(1)} kW</strong></div><div class="machine-metric"><label>Health score</label><strong>${Number.isFinite(m.health)?`${m.health} / 100`:'No check yet'}</strong><div class="machine-progress"><span style="width:${m.health}%"></span></div></div><div class="machine-metric"><label>Normal power</label><strong>${m.normal.toFixed(1)} kW</strong></div><div class="machine-metric"><label>Last checked</label><strong style="font-size:11px">${m.last}</strong></div></div><div class="small">${m.idle?`Idle for ${m.idleMinutes||20} min`:'Meter connected'} <span style="float:right;color:var(--green);font-weight:700">Details →</span></div></article>`).join('')}</div>`}
function openMachine(id){selectedMachine=id;view='machine';render()}
function machineDetail(){let m=db.machines.find(x=>x.id===selectedMachine)||db.machines[0],tests=db.healthTests.filter(x=>x.machineId===m.id).slice(0,4);return `<button class="back-link" onclick="go('machines')">← ${t('Machines')}</button>${pageHead(esc(m.name),`${m.id} · ${esc(m.type)} · Last meter update ${m.last}`,`<button class="button" onclick="startWorkflow('health','${m.id}')">⌁ &nbsp; Run health check</button>`)}<div class="cards detail-kpis"><article class="card detail-kpi"><label>Current status</label><strong style="font-size:14px">${badge(m.state)}</strong></article><article class="card detail-kpi"><label>Current power</label><strong>${m.power.toFixed(1)} <small style="font:500 11px 'DM Sans'">kW</small></strong></article><article class="card detail-kpi"><label>Normal operating power</label><strong>${m.normal.toFixed(1)} <small style="font:500 11px 'DM Sans'">kW</small></strong></article><article class="card detail-kpi"><label>Health score</label><strong>${Number.isFinite(m.health)?m.health:'—'} <small style="font:500 11px 'DM Sans'">${Number.isFinite(m.health)?'/ 100':''}</small></strong></article></div><div class="detail-grid"><article class="card panel"><div class="panel-head"><div><div class="panel-title">Today's consumption</div><div class="panel-subtitle">Power pattern · kW</div></div></div>${chart([18,24,21,33,28,43,39,55,44,58,49,62],`m${m.id}`)}<div class="section-head"><h2>Health tests</h2><span>Today</span></div>${tests.length?tests.map(x=>`<div class="list-row"><span>${esc(x.time)} · Health check ${x.modelScope?.startsWith('Legacy demo')?'<small>(legacy demo)</small>':''}</span><span>${x.health}/100 &nbsp; ${badge(x.status)}</span></div>`).join(''):`<div class="empty-state"><strong>No checks recorded today</strong>Run a machine health check to add a result.</div>`}</article><article class="card panel"><div class="panel-head"><div><div class="panel-title">Machine information</div><div class="panel-subtitle">Meter and operating baseline</div></div></div><div class="list-row"><span>Machine ID</span><strong>${m.id}</strong></div><div class="list-row"><span>Machine type</span><strong>${esc(m.type)}</strong></div><div class="list-row"><span>Idle threshold</span><strong>&lt; 3.0 kW</strong></div><div class="list-row"><span>Idle duration</span><strong>${m.idle?`${m.idleMinutes||20} minutes`:'Not idle'}</strong></div><div class="section"><div class="panel-title">Related alerts</div><div style="margin-top:12px">${alertList(db.alerts.filter(a=>a.machineId===m.id&&!a.resolved))}</div></div></article></div>`}
function monitorPage(){return `${pageHead('Monitor','Choose a check or open live readings. Sensor checks use this device where supported.')}<div class="cards monitor-grid"><article class="card monitor-card"><div class="feature-title"><span class="feature-mark">⌁</span>Machine Health</div><p>Record machine sound and vibration, then compare with the meter reading and normal baseline.</p><div class="small" style="margin-bottom:13px">Audio + motion sensor · about 20 seconds</div><button class="button" onclick="startWorkflow('health')">${t('StartCheck')} →</button></article><article class="card monitor-card"><div class="feature-title"><span class="feature-mark">◖</span>Air Leak Detection</div><p>Record the area around a compressor or air line and check for a possible continuous high-frequency sound.</p><div class="small" style="margin-bottom:13px">Microphone · about 8 seconds</div><button class="button" onclick="startWorkflow('leak')">Scan for leak →</button></article><article class="card monitor-card"><div class="feature-title"><span class="feature-mark">◴</span>Idle Monitoring</div><p>Meter readings are checked on a 10-minute cycle against configured machine thresholds.</p><div class="small" style="margin-bottom:13px">${db.machines.filter(m=>m.idle).length} machines currently idle</div><button class="button secondary" onclick="go('idle')">View idle machines →</button></article><article class="card monitor-card"><div class="feature-title"><span class="feature-mark">ϟ</span>Peak Demand</div><p>See current factory demand against the maximum allowed demand you set.</p><div class="small" style="margin-bottom:13px">${demand().toFixed(1)} / ${db.limit} kW</div><button class="button secondary" onclick="go('demand')">View demand →</button></article></div>`}
function startWorkflow(kind,machine=''){workflow={kind,step:0,machine,audio:null,vibration:null};view=kind==='health'?'health':'leak';render()}
function workflowPage(){const health=workflow.kind==='health',title=health?'Machine Health Check':'Compressed Air Leak Detection';if(workflow.step===0)return `<button class="back-link" onclick="go('monitor')">← Monitor</button>${pageHead(title,health?'Record sound and vibration to check a machine against its normal baseline.':'Record the sound around a compressor or air line to screen for an abnormal sound pattern.')}<div class="workflow"><div class="card workflow-card"><div class="stepper"><div class="step current"><span class="step-num">1</span> Machine</div><div class="step"><span class="step-num">2</span> Recording</div><div class="step"><span class="step-num">3</span> Result</div></div><label class="form-label" for="machine-select">${health?'Select machine':'Machine or location'}</label><select class="select" id="machine-select"><option value="">Choose a machine</option>${db.machines.map(m=>`<option value="${m.id}" ${workflow.machine===m.id?'selected':''}>${esc(m.name)} · ${m.id}</option>`).join('')}<option value="custom">Other location…</option></select><div class="helper">Choose the machine being checked. Machine names are configurable in Settings.</div><div id="custom-location"></div><div class="device-note">${health?'UrjaDrishti uses your microphone for machine sound and your motion sensor for vibration. Record near the machine and follow your site safety rules.':'UrjaDrishti records microphone audio and checks it with the trained valve sound anomaly model. An abnormal sound is not proof of an air leak.'}</div><button class="button full" style="margin-top:10px" onclick="continueWorkflow()">${t('Continue')} →</button></div></div>`;
 if(workflow.step===1){let stage=health?(workflow.recordingStage||'audio'):'audio',isVib=stage==='vibration';return `<button class="back-link" onclick="workflowBack()">← ${t('Back')}</button>${pageHead(title,esc(workflow.machineName||machineName(workflow.machine)))}<div class="workflow"><div class="card workflow-card"><div class="stepper"><div class="step done"><span class="step-num">✓</span> Machine</div><div class="step current"><span class="step-num">2</span> Recording</div><div class="step"><span class="step-num">3</span> Result</div></div><div class="record-box"><div class="record-orb ${workflow.recording?'recording':''}">${isVib?'⌁':'◖'}</div><h3>${workflow.recording?'Recording…':isVib?'Vibration recording':'Audio recording'}</h3><p>${workflow.recording?`Keep the phone in place. ${workflow.seconds||8} seconds remaining.`:isVib?'Place the phone securely near the machine. Motion sensor access will be requested where supported.':'Place the phone near the machine. Allow microphone access when your browser asks.'}<br>Recommended recording: 8 seconds.</p>${workflow.recording?`<div class="progress-track"><div class="progress-bar" style="width:${((8-(workflow.seconds||8))/8)*100}%"></div></div><button class="button secondary" onclick="stopRecording()">Stop recording</button>`:`<div class="record-actions"><button class="button" onclick="record('${isVib?'vibration':'audio'}')">◉ &nbsp; ${t('StartRecording')}</button></div>`}${workflow[stage+'Done']?`<div class="record-result"><strong>${isVib?'Vibration':'Audio'} recorded ✓</strong><br>Captured samples: ${isVib?(workflow.vibration?.count||0):`${(workflow.audio?.duration||8).toFixed(1)} seconds of microphone audio`}<br>${isVib?'Real device motion':'Real microphone audio'} · ready for model analysis</div>`:''}</div>${workflow[stage+'Done']?`<button class="button full" onclick="nextRecording()">${health&&!isVib?'Continue to vibration':'Analyze readings'} →</button>`:''}</div></div>`}
 return health?healthResult():leakResult()}
function machineName(id){return db.machines.find(m=>m.id===id)?.name||id||'Selected location'}
function workflowBack(){if(workflow.step===1){workflow.step=0;workflow.recording=false;render()}else go('monitor')}
function continueWorkflow(){const s=document.getElementById('machine-select');if(!s?.value){toast('Select a machine or location to continue.','warn');return}if(s.value==='custom'&&workflow.kind==='health'){toast('Machine health checks require a configured machine with a meter baseline.','warn');return}if(s.value==='custom'){const inp=document.getElementById('custom-name');if(!inp?.value.trim()){toast('Enter the machine or location name.','warn');return}workflow.machine='custom';workflow.machineName=inp.value.trim()}else{workflow.machine=s.value;workflow.machineName=machineName(s.value)}workflow.step=1;workflow.recordingStage='audio';render()}
function recordingTimer(type){workflow.recording=true;workflow.seconds=8;workflow.startedAt=performance.now();render();recordTimer=setInterval(()=>{workflow.seconds--;render();if(workflow.seconds<=0)finishRecording(type)},1000)}
function wavBlob(samples,sampleRate){const pcm=new Int16Array(samples.length);for(let i=0;i<samples.length;i++)pcm[i]=Math.max(-1,Math.min(1,samples[i]))*(samples[i]<0?32768:32767);const buffer=new ArrayBuffer(44+pcm.length*2),view=new DataView(buffer);const str=(offset,value)=>{for(let i=0;i<value.length;i++)view.setUint8(offset+i,value.charCodeAt(i))};str(0,'RIFF');view.setUint32(4,36+pcm.length*2,true);str(8,'WAVE');str(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,sampleRate,true);view.setUint32(28,sampleRate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);str(36,'data');view.setUint32(40,pcm.length*2,true);new Int16Array(buffer,44).set(pcm);return new Blob([buffer],{type:'audio/wav'})}
async function normalizeMicRecording(blob){const AudioCtx=window.AudioContext||window.webkitAudioContext,OfflineCtx=window.OfflineAudioContext||window.webkitOfflineAudioContext;if(!AudioCtx||!OfflineCtx)throw new Error('This browser cannot decode microphone audio for analysis.');const ctx=new AudioCtx();try{const decoded=await ctx.decodeAudioData(await blob.arrayBuffer()),length=16000*8,offline=new OfflineCtx(1,length,16000),source=offline.createBufferSource();source.buffer=decoded;source.connect(offline.destination);source.start(0);const rendered=await offline.startRendering();return wavBlob(rendered.getChannelData(0),16000)}finally{await ctx.close()}}
async function record(type){if(workflow.recording)return;workflow[type+'File']=null;workflow[type+'Done']=false;if(type==='audio'){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Microphone recording is not supported in this browser.','error');return}try{recordStream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:false,noiseSuppression:false,autoGainControl:false}});audioChunks=[];audioRecorder=new MediaRecorder(recordStream);audioRecorder.ondataavailable=e=>{if(e.data?.size)audioChunks.push(e.data)};audioRecorder.onstop=async()=>{try{const raw=new Blob(audioChunks,{type:audioRecorder.mimeType||'audio/webm'});const duration=(performance.now()-workflow.startedAt)/1000;if(duration<6)throw new Error('Record at least 6 seconds of machine sound before analyzing.');workflow.audioBlob=await normalizeMicRecording(raw);workflow.audio={duration,quality:'Captured'};workflow.audioDone=true;workflow.recording=false;render()}catch(error){workflow.recording=false;toast(error.message||'Unable to process recorded audio. Try again.','error');render()}finally{recordStream?.getTracks().forEach(track=>track.stop());recordStream=null;audioRecorder=null}};audioRecorder.start();recordingTimer('audio')}catch(error){recordStream?.getTracks().forEach(track=>track.stop());recordStream=null;toast(error.name==='NotAllowedError'?'Microphone permission is required for real audio analysis.':'Could not start the microphone. Check browser permissions and try again.','error')}return}
let motionAvailable=typeof DeviceMotionEvent!=='undefined';if(!motionAvailable){toast('This device does not provide the required motion sensor.','error');return}try{if(typeof DeviceMotionEvent.requestPermission==='function')motionAvailable=(await DeviceMotionEvent.requestPermission())==='granted'}catch{motionAvailable=false}if(!motionAvailable){toast('Motion sensor permission is required for real vibration analysis.','error');return}workflow.motionSamples=[];motionHandler=e=>{const a=e.acceleration||e.accelerationIncludingGravity;if(a&&Number.isFinite(a.x)&&Number.isFinite(a.y)&&Number.isFinite(a.z))workflow.motionSamples.push({t:performance.now(),x:a.x,y:a.y,z:a.z})};window.addEventListener('devicemotion',motionHandler);recordingTimer('vibration')}
function finishRecording(type){clearInterval(recordTimer);recordTimer=null;workflow.recording=false;if(type==='audio'){if(audioRecorder&&audioRecorder.state!=='inactive')audioRecorder.stop();else toast('Microphone recording did not start.','error');return}if(motionHandler){window.removeEventListener('devicemotion',motionHandler);motionHandler=null}const samples=workflow.motionSamples||[];if(samples.length<8){toast('Not enough real motion samples were captured. Check sensor support and try again.','error');workflow.vibrationDone=false;render();return}const elapsed=(samples.at(-1).t-samples[0].t)/1000;if(elapsed<6){toast('Record for at least 6 seconds to capture enough real vibration samples.','error');workflow.vibrationDone=false;render();return}const rate=(samples.length-1)/Math.max(elapsed,.01);workflow.vibrationFile=null;workflow.vibration={samples:samples.map(({t,x,y,z})=>[t,x,y,z]),sample_rate_hz:rate,count:samples.length,duration:elapsed};workflow.vibrationDone=true;render()}
function stopRecording(){finishRecording(workflow.recordingStage==='audio'?'audio':'vibration')}
async function blobBase64(blob){const bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary)}
async function nextRecording(){if(workflow.kind==='health'&&workflow.recordingStage==='audio'){workflow.recordingStage='vibration';render();return}workflow.step=2;workflow.processing=true;render();try{const token=await window.urjaGetIdToken?.();if(!token)throw new Error('Sign in with your Firebase account before running model analysis.');let endpoint,payload,options;if(workflow.kind==='health'){const machine=db.machines.find(m=>m.id===workflow.machine);const form=new FormData();form.append('machine_id',workflow.machine);form.append('current_power_kw',String(machine?.power??0));form.append('normal_power_kw',String(machine?.normal??0));const audioFile=workflow.audioFile||workflow.audioBlob;if(!audioFile)throw new Error('Choose an audio upload or record machine audio.');form.append('audio_file',audioFile,workflow.audioFile?.name||'recording.wav');if(workflow.vibrationFile)form.append('vibration_file',workflow.vibrationFile,workflow.vibrationFile.name);else if(workflow.vibration?.samples?.length)form.append('vibration_samples',JSON.stringify(workflow.vibration));else throw new Error('Choose a vibration CSV or record device motion.');endpoint='/api/ml/machine-health';options={method:'POST',headers:{'Authorization':`Bearer ${token}`},body:form}}else{const form=new FormData();form.append('machine_id',workflow.machine);const audioFile=workflow.audioFile||workflow.audioBlob;if(audioFile)form.append('audio_file',audioFile,workflow.audioFile?.name||'recording.wav');else throw new Error('Choose a valve WAV upload or record audio before analyzing.');endpoint='/api/ml/air-leak';options={method:'POST',headers:{'Authorization':`Bearer ${token}`},body:form}}const response=await fetch(mlApiUrl(endpoint),options);let result;try{result=await response.json()}catch{throw new Error('Prediction service returned an unreadable response.')}if(!response.ok)throw new Error(result.detail||'Prediction service is unavailable.');persistResult(result);workflow.processing=false;render()}catch(error){workflow.processing=false;workflow.step=1;toast(error.message||'The prediction service is temporarily unavailable.','error');render()}}
function persistResult(result){const now=timeNow();if(workflow.kind==='health'){let m=db.machines.find(x=>x.id===workflow.machine);let row={machineId:workflow.machine,machineName:workflow.machineName,time:now,date:new Date().toISOString().slice(0,10),electricity:m?.power??0,electrical:result.electrical_anomaly,audio:result.audio_anomaly,audio_anomaly_score:result.audio_anomaly,vibration:result.vibration_anomaly,vibration_anomaly_score:result.vibration_anomaly,electrical_anomaly_score:result.electrical_anomaly,health:result.health_score,status:result.status,reason:result.possible_reason,timestamp:Date.now(),modelScope:result.model_scope};db.healthTests.unshift(row);if(m){m.health=row.health;m.state=row.status==='Healthy'?'Running':row.status;m.last=now;m.reason=row.reason}if(row.health<80)addAlert('Machine Health',`${workflow.machineName} health check needs attention.`,workflow.machine,'warning');save();workflow.result=row}else{let row={machineId:workflow.machine,machineName:workflow.machineName,time:now,score:result.leak_score,leak:!!result.leak_candidate,reason:result.possible_reason,timestamp:Date.now(),modelScope:result.model_scope};db.leakScans.unshift(row);if(row.leak)addAlert('Air Leak',`Abnormal valve sound candidate detected near ${workflow.machineName}.`,workflow.machine,'warning');save();workflow.result=row}}
function healthResult(){let r=workflow.result;if(!r)return `<div class="card workflow-card"><div class="record-box"><h3>Analyzing readings…</h3><p>Audio, vibration and meter readings are being compared with the machine baseline.</p></div></div>`;let cl=r.health>=80?'':r.health>=60?'warn':'bad';return `<button class="back-link" onclick="go('monitor')">← Monitor</button>${pageHead('Machine Health Result',`${esc(r.machineName)} · Checked ${r.time}`)}<div class="workflow"><article class="card workflow-card"><div class="stepper"><div class="step done"><span class="step-num">✓</span> Machine</div><div class="step done"><span class="step-num">✓</span> Recording</div><div class="step current"><span class="step-num">3</span> Result</div></div><div style="text-align:center;padding:10px"><div class="eyebrow">HEALTH SCORE</div><div class="result-score">${r.health}<small> / 100</small></div>${badge(r.status)}<div class="result-banner ${cl}"><strong>${r.status==='Healthy'?'✓ HEALTHY':r.status==='Attention'?'⚠ ATTENTION':'⚠ POSSIBLE FAULT'}</strong><div class="result-reason"><b>Possible reason</b><br>${esc(r.reason)}</div></div><div class="result-metrics"><div class="metric-chip">Electrical anomaly<strong>${r.electrical} / 100</strong></div><div class="metric-chip">Audio anomaly<strong>${r.audio} / 100</strong></div><div class="metric-chip">Vibration anomaly<strong>${r.vibration} / 100</strong></div></div><div class="small" style="margin:14px 0">Meter reading: ${Number(r.electricity).toFixed(1)} kW · saved ${r.time}</div><div class="small">Experimental dataset models · phone-to-machine transfer is not validated.</div></div><button class="button secondary full" onclick="openMachine('${r.machineId}')">View machine →</button><button class="link-button" style="width:100%" onclick="startWorkflow('health')">Check another machine</button></article></div>`}
function leakResult(){let r=workflow.result;if(!r)return `<div class="card workflow-card"><div class="record-box"><h3>Analyzing sound…</h3><p>Sending the recording to the trained valve sound anomaly model.</p></div></div>`;return `<button class="back-link" onclick="go('monitor')">← Monitor</button>${pageHead('Air Leak Result',`${esc(r.machineName)} · Sound scan at ${r.time}`)}<div class="workflow"><article class="card workflow-card"><div class="eyebrow">${r.leak?'ABNORMAL SOUND FLAGGED':'NO ABNORMAL SOUND FLAGGED'}</div><div class="result-score">${r.score}<small> / 100</small></div>${badge(r.leak?'Attention':'Running')}<div class="result-banner ${r.leak?'warn':''}"><strong>${r.leak?'⚠ ABNORMAL SOUND CANDIDATE':'✓ NO ABNORMAL SOUND FLAGGED'}</strong><div class="result-reason"><b>Possible reason</b><br>${esc(r.reason)}</div></div><div class="list-row"><span>Machine / location</span><strong>${esc(r.machineName)}</strong></div><div class="list-row"><span>Detected at</span><strong>${r.time}</strong></div><button class="button secondary full" style="margin-top:15px" onclick="startWorkflow('leak')">Scan another location</button></article></div>`}
function idlePage(){let idle=db.machines.filter(m=>m.idle),run=db.machines.filter(m=>!m.idle);return `${pageHead('Idle Monitoring','Meter readings are evaluated every 10 minutes. Machines below their configured threshold for over 10 minutes raise an alert.')}<div class="cards summary-grid"><article class="card stat-card"><div class="stat-head">Machines idle<span class="stat-icon">◴</span></div><div class="stat-value">${idle.length}</div><div class="stat-foot">Across ${db.machines.length} monitored machines</div></article><article class="card stat-card"><div class="stat-head">Monitoring interval<span class="stat-icon">◷</span></div><div class="stat-value">10 <small style="font:500 12px 'DM Sans'">min</small></div><div class="stat-foot">Next meter check updates automatically</div></article></div><div class="section"><div class="section-head"><h2>Idle or standby</h2><span>${idle.length} machines</span></div><div class="card panel">${idle.length?`<div class="table-wrap"><table class="machine-table"><thead><tr><th>MACHINE</th><th>STATUS</th><th>NORMAL POWER</th><th>CURRENT</th><th>IDLE DURATION</th><th>THRESHOLD</th></tr></thead><tbody>${idle.map(m=>`<tr onclick="openMachine('${m.id}')"><td><div class="machine-name">${esc(m.name)}</div><div class="machine-id">${m.id}</div></td><td>${badge('Idle')}</td><td>${m.normal.toFixed(1)} kW</td><td>${m.power.toFixed(1)} kW</td><td>${m.idleMinutes||20} min</td><td>&lt; ${m.threshold||3.0} kW</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><strong>No idle machines detected</strong>Meter readings are checked every 10 minutes.</div>`}</div></div><div class="section"><div class="section-head"><h2>Running normally</h2><span>${run.length} machines</span></div><div class="card panel"><div class="table-wrap"><table class="machine-table"><thead><tr><th>MACHINE</th><th>STATUS</th><th>NORMAL POWER</th><th>CURRENT</th><th>LAST CHECKED</th></tr></thead><tbody>${run.map(m=>`<tr onclick="openMachine('${m.id}')"><td><div class="machine-name">${esc(m.name)}</div><div class="machine-id">${m.id}</div></td><td>${badge(m.state)}</td><td>${m.normal.toFixed(1)} kW</td><td>${m.power.toFixed(1)} kW</td><td>${m.last}</td></tr>`).join('')}</tbody></table></div></div></div>`}
function demandPage(){let d=demand(),over=d>db.limit;return `${pageHead('Peak Demand','Keep current electricity demand in view against your configured factory limit.')}<div class="dashboard-grid"><div><article class="demand-card" style="padding:25px"><div class="demand-head">CURRENT FACTORY DEMAND</div><div class="demand-main"><strong style="font-size:42px">${d.toFixed(1)}</strong><span>/ ${db.limit} kW allowed</span></div><div class="demand-meter"><div class="demand-fill" style="width:${Math.min(100,d/db.limit*100)}%"></div></div><div class="demand-foot"><span>${over?'⚠ LIMIT EXCEEDED':'NORMAL'}</span><span>${over?`${(d-db.limit).toFixed(1)} kW exceeded`:`${(db.limit-d).toFixed(1)} kW available`}</span></div></article><article class="card panel"><div class="panel-head"><div><div class="panel-title">Today's demand pattern</div><div class="panel-subtitle">Simulated meter readings · checked every 10 minutes</div></div></div>${chart([45,53,51,62,69,64,77,72,87,81,94,Math.min(d,110)],'demandChart')}</article></div><article class="card panel"><div class="panel-title">Demand settings</div><p class="panel-subtitle">Set the maximum allowed demand for this factory.</p><label class="form-label" for="demandLimit">Maximum allowed demand (kW)</label><input id="demandLimit" class="input" type="number" min="1" value="${db.limit}"><button class="button" style="margin-top:12px" onclick="saveLimit()">Save limit</button><div class="device-note">If the next meter update shows demand above this limit, a peak demand alert will appear. Decisions about stopping machines remain with factory management.</div></article></div><div class="section"><div class="section-head"><h2>Machines contributing to demand</h2><span>Current readings</span></div><div class="card panel"><div class="table-wrap"><table class="machine-table"><thead><tr><th>MACHINE</th><th>STATUS</th><th>POWER</th><th>HEALTH</th></tr></thead><tbody>${db.machines.map(m=>`<tr onclick="openMachine('${m.id}')"><td><div class="machine-name">${esc(m.name)}</div><div class="machine-id">${m.id}</div></td><td>${badge(m.state)}</td><td>${m.power.toFixed(1)} kW</td><td>${Number.isFinite(m.health)?`${m.health}/100`:'—'}</td></tr>`).join('')}</tbody></table></div></div></div>`}
function alertsPage(){return `${pageHead('Alerts','Monitoring events for this factory. Review or resolve an alert after checking the machine.')}<div class="pill-row" style="margin-bottom:13px"><span class="status">${db.alerts.filter(a=>!a.resolved).length} active</span><span class="status neutral">${db.alerts.filter(a=>a.resolved).length} resolved</span><button class="link-button" onclick="markRead()">Mark all read</button></div><div class="card panel">${db.alerts.length?`<div class="alert-list">${db.alerts.map(a=>`<div class="alert-item"><div class="alert-icon">${a.type==='Peak Demand'?'ϟ':a.type==='Air Leak'?'◖':a.type==='Idle'?'◴':'⌁'}</div><div style="flex:1"><div class="alert-text">${esc(a.title)}</div><div class="alert-meta">${esc(a.message)} · ${esc(a.time)}</div><div class="alert-meta">${a.type} · ${a.machineId||'Factory'} · ${a.resolved?'Resolved':'Active'}</div></div>${!a.resolved?`<button class="button secondary" style="padding:7px 9px;font-size:10px" onclick="resolveAlert('${a.id}')">Resolve</button>`:badge('Resolved')}</div>`).join('')}</div>`:`<div class="empty-state"><strong>No alerts yet</strong>Idle, demand, health, and leak alerts will appear here.</div>`}</div>`}
function reportsPage(){let c=healthCounts(),d=demand();return `${pageHead('Daily Reports','Generate a concise one-day report from the data stored in this prototype.')}<div class="workflow"><div class="card workflow-card"><div class="panel-title">Owner verification</div><p class="helper">Enter the 4-digit report code to prepare today's factory report.</p><label class="form-label" for="report-code">Owner code</label><input id="report-code" class="input" type="password" inputmode="numeric" maxlength="4" placeholder="••••"><button class="button full" style="margin-top:14px" onclick="generateReport()">▤ &nbsp; ${t('Generate')}</button></div>${db.reportGenerated?`<div class="report-preview section" id="report"><div class="report-head"><div><div class="report-logo">◉ UrjaDrishti</div><div class="small">Daily Factory Monitoring Report</div></div><div style="text-align:right;font-size:10px"><strong>${esc(db.factory)}</strong><div class="small">${dateNow()} · Generated ${timeNow()}</div></div></div><div class="report-kpis"><div><small>Total energy today</small><strong>1,248 kWh</strong></div><div><small>Peak demand</small><strong>${d.toFixed(1)} kW</strong></div><div><small>Machine checks</small><strong>${countRealChecks()}</strong></div></div><h3 style="font:700 13px Manrope">Machine status summary</h3><div class="list-row"><span>Healthy</span><strong>${c.healthy}</strong></div><div class="list-row"><span>Attention</span><strong>${c.attention}</strong></div><div class="list-row"><span>Possible fault</span><strong>${c.fault}</strong></div><div class="section"><h3 style="font:700 13px Manrope">Machine readings</h3><div class="table-wrap"><table class="machine-table"><thead><tr><th>MACHINE</th><th>STATUS</th><th>POWER</th><th>HEALTH</th></tr></thead><tbody>${db.machines.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.state)}</td><td>${m.power.toFixed(1)} kW</td><td>${m.health}</td></tr>`).join('')}</tbody></table></div></div><div class="section"><h3 style="font:700 13px Manrope">Alerts today</h3>${alertList(db.alerts)}</div><p class="small" style="margin-top:20px">Prototype report · Based on simulated meter readings and stored demo checks. Not an industrial assessment.</p></div><div class="pill-row" style="justify-content:center;margin-top:12px"><button class="button" onclick="window.print()">Print / Save as PDF</button></div>`:''}</div>`}
function settingsPage(){return `${pageHead('Settings','Configure this factory, machine thresholds, notifications, and owner report access.')}<div class="settings-grid"><article class="card settings-card"><h2>Factory information</h2><p>This account represents one factory.</p><div class="field-row"><div><label class="form-label">Factory name</label><input id="factory-name" class="input" value="${esc(db.factory)}"></div><div><label class="form-label">Location</label><input id="factory-location" class="input" value="${esc(db.location)}"></div></div><button class="button" style="margin-top:13px" onclick="saveFactory()">Save factory</button></article><article class="card settings-card"><h2>Energy configuration</h2><p>Values are used in meter summaries and demand checks.</p><div class="field-row"><div><label class="form-label">Electricity cost (₹ / kWh)</label><input id="energy-cost" class="input" type="number" value="${db.cost}"></div><div><label class="form-label">Maximum demand (kW)</label><input id="settings-limit" class="input" type="number" value="${db.limit}"></div></div><label class="form-label">Factory start time</label><input id="factory-start" class="input" type="time" value="${db.start}"><button class="button" style="margin-top:13px" onclick="saveEnergy()">Save energy settings</button></article><article class="card settings-card"><h2>Machines</h2><p>${db.machines.length} configurable machine records.</p><button class="button secondary" onclick="addMachine()">＋ Add a machine</button><div style="margin-top:14px">${db.machines.slice(0,4).map(m=>`<div class="list-row"><span>${esc(m.name)} <span class="small">${m.id}</span></span><strong>${m.normal.toFixed(1)} kW baseline</strong></div>`).join('')}</div></article><article class="card settings-card"><h2>Notifications</h2><p>Website notification center is always available as a fallback.</p><label class="checkbox-line"><input type="checkbox" id="push-check" ${db.notificationsEnabled?'checked':''}> Enable browser notifications on this device</label><button class="button secondary" onclick="registerNotifications()">Register this device</button><div class="small" style="margin-top:10px">Registered devices: ${db.devices.length}${db.devices.map(d=>`<br>· ${esc(d.name)} · registered ${esc(d.at)}`).join('')}</div></article><article class="card settings-card"><h2>Language</h2><p>Navigation and key labels support Indian languages.</p><select class="select" onchange="setLang(this.value)"><option value="en" ${db.language==='en'?'selected':''}>English</option><option value="hi" ${db.language==='hi'?'selected':''}>Hindi</option><option value="pa" ${db.language==='pa'?'selected':''}>Punjabi</option><option value="mr" ${db.language==='mr'?'selected':''}>Marathi</option><option value="ta" ${db.language==='ta'?'selected':''}>Tamil</option><option value="gu" ${db.language==='gu'?'selected':''}>Gujarati (labels ready to extend)</option><option value="bn" ${db.language==='bn'?'selected':''}>Bengali (labels ready to extend)</option><option value="kn" ${db.language==='kn'?'selected':''}>Kannada (labels ready to extend)</option></select></article><article class="card settings-card"><h2>Owner security</h2><p>Change the 4-digit code required to generate reports.</p><label class="form-label">New report code</label><input id="new-code" class="input" type="password" inputmode="numeric" maxlength="4" placeholder="4 digits"><button class="button secondary" style="margin-top:13px" onclick="setReportCode()">Update report code</button><div class="small" style="margin-top:9px">Demo code is 2468 until changed.</div></article></div>`}
function landing(){return `<div class="landing"><nav class="landing-nav"><a class="landing-brand" href="#"><div class="brand-mark">U</div><div class="brand-name">UrjaDrishti<small style="color:var(--muted)">FACTORY INTELLIGENCE</small></div></a><div class="landing-links"><a href="#features">Features</a><a href="#how">How it works</a><select class="lang-select" onchange="setLang(this.value)"><option value="en">English</option><option value="hi">हिन्दी</option><option value="pa">ਪੰਜਾਬੀ</option><option value="mr">मराठी</option><option value="ta">தமிழ்</option></select><button class="button secondary" onclick="showAuth()">${t('Login')}</button></div></nav><section class="landing-hero"><div class="hero-copy"><div class="hero-kicker">A clearer view of your factory</div><h1>Smarter energy.<br><span>Healthier machines.</span></h1><p>UrjaDrishti helps SMEs monitor machine health, detect energy waste, identify compressed-air leaks, and stay within electricity demand limits using practical sensors and smartphones.</p><div class="hero-buttons"><button class="button" onclick="enterDemo()">${t('Explore')} &nbsp; →</button><button class="button secondary" onclick="showAuth()">${t('Login')}</button></div><div class="hero-note">Designed for small and medium-sized factories · English + Indian languages</div></div><div class="hero-visual"><div class="hero-chip one">Factory demand<strong>94.6 kW <span style="font-size:10px;color:var(--green)">NORMAL</span></strong></div><div class="hero-chip two">Machines monitored<strong>9 connected</strong></div><div class="hero-chip three">Today's energy<strong>1,248 kWh</strong></div><div class="factory-illustration"><div class="factory-roof"></div><div class="factory-base"></div><div class="factory-window"></div><div class="factory-window two"></div><div class="factory-window three"></div><div class="factory-door"></div></div></div></section><section class="landing-section alt"><div class="landing-container"><div class="center-heading"><div class="eyebrow">The challenges are easy to miss</div><h2>Small changes can go unnoticed</h2><p>Machines and energy use can tell you something is wrong—if you have a practical way to listen.</p></div><div class="problem-grid"><div class="problem-item"><span>⌁</span>Machines can fail silently.</div><div class="problem-item"><span>ϟ</span>Energy can be wasted silently.</div><div class="problem-item"><span>◖</span>Compressed air can leak silently.</div><div class="problem-item"><span>◷</span>Peak demand can rise unexpectedly.</div></div></div></section><section id="features" class="landing-section"><div class="landing-container"><div class="center-heading"><div class="eyebrow">One practical monitoring platform</div><h2>See the signals that matter</h2><p>Bring meter readings and smartphone sensors together in a clear, worker-friendly view.</p></div><div class="solution-grid"><div class="solution-item"><span>⌁</span>Machine health<small>Compare sound, vibration, and electricity readings with a machine's baseline.</small></div><div class="solution-item"><span>◖</span>Air leak detection<small>Use a phone microphone to scan for a possible compressed-air leak.</small></div><div class="solution-item"><span>◴</span>Idle energy monitoring<small>Spot machines drawing power below their normal operating level.</small></div><div class="solution-item"><span>ϟ</span>Peak demand monitoring<small>See current factory demand beside your configured limit.</small></div></div></div></section><section id="how" class="landing-section alt"><div class="landing-container"><div class="center-heading"><div class="eyebrow">How it works</div><h2>From machine to useful alert</h2></div><div class="how-grid"><div class="how-step"><span>⚙</span>Machine</div><div class="how-arrow">→</div><div class="how-step"><span>ϟ</span>Meter + phone</div><div class="how-arrow">→</div><div class="how-step"><span>⌁</span>Detection & alert</div></div></div></section><section class="landing-section"><div class="landing-container"><div class="landing-cta"><div><h2>Bring better visibility to your factory.</h2><p>See what your machines are consuming. Detect problems earlier. Review energy use in one place.</p></div><button class="button" onclick="enterDemo()">Get started →</button></div></div></section><footer class="landing-footer"><span>◉ UrjaDrishti · Practical factory monitoring</span><span>Prototype demo · Sample data · No industrial accuracy claims</span></footer></div>`}
function authModal(){return `<div class="auth-overlay" onclick="if(event.target===this)closeAuth()"><div class="auth-card"><button class="close-btn" onclick="closeAuth()">×</button><div class="brand-mark">U</div><h2>Welcome to UrjaDrishti</h2><p>Sign in or create a local prototype account for your factory.</p><label class="form-label">Your name</label><input class="input" id="auth-name" placeholder="Factory owner or manager" value="Factory Admin"><label class="form-label">Factory name</label><input class="input" id="auth-factory" placeholder="Your factory" value="${esc(db.factory)}"><label class="checkbox-line"><input type="checkbox" id="auth-register" checked> Register this device for browser notifications</label><button class="button full" style="margin-top:12px" onclick="login()">Continue to factory dashboard</button><div class="small" style="text-align:center;margin-top:12px">Prototype sign-in · no account or password required</div></div></div>`}
function render(){let app=document.getElementById('app');if(!db.loggedIn){app.innerHTML=landing()+(document.querySelector('.auth-overlay')?'':'');return}let body=({overview:dashboard,machines:machinesPage,monitor:monitorPage,health:workflowPage,leak:workflowPage,idle:idlePage,demand:demandPage,alerts:alertsPage,reports:reportsPage,settings:settingsPage,machine:machineDetail})[view]?.()||dashboard();app.innerHTML=shell(body);if(document.getElementById('auth-modal-root'))document.getElementById('auth-modal-root').remove()}
function toast(msg,type=''){let el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;document.getElementById('toast-region').append(el);setTimeout(()=>el.remove(),3400)}
function go(v){view=v;render();window.scrollTo(0,0)}function setLang(v){db.language=v;save();render()}function enterDemo(){db.loggedIn=true;save();view='overview';if(!db.devices.length)db.devices.push({name:'This browser',at:timeNow()});save();render()}
function showAuth(){document.body.insertAdjacentHTML('beforeend',authModal())}function closeAuth(){document.querySelector('.auth-overlay')?.remove()}function login(){let name=document.getElementById('auth-name').value.trim(),factory=document.getElementById('auth-factory').value.trim();if(factory)db.factory=factory;db.loggedIn=true;if(document.getElementById('auth-register').checked&&!db.devices.length)db.devices.push({name:'This browser',at:timeNow()});db.user=name||'Factory Admin';save();closeAuth();view='overview';render();toast(`Welcome${name?`, ${name}`:''}. Factory dashboard ready.`)}
function addAlert(type,message,machineId,severity='warning'){let key=type+machineId+message;if(db.alerts.some(a=>!a.resolved&&a.key===key))return;db.alerts.unshift({id:Date.now().toString(36)+Math.random().toString(36).slice(2,5),key,type,title:type==='Idle'?`Machine ${machineId} has been idle for more than 10 minutes`:type==='Peak Demand'?'Peak demand limit exceeded':type==='Air Leak'?message:`${machineName(machineId)} health check needs attention`,message,time:timeNow(),machineId,severity,resolved:false,read:false});if(db.notificationsEnabled&&'Notification'in window&&Notification.permission==='granted')new Notification('UrjaDrishti alert',{body:message});save()}
function resolveAlert(id){let a=db.alerts.find(x=>x.id===id);if(a){a.resolved=true;a.read=true;save();render();toast('Alert marked as resolved.')}}function markRead(){db.alerts.forEach(a=>a.read=true);save();render();toast('Notifications marked as read.')}
async function registerNotifications(){db.notificationsEnabled=!!document.getElementById('push-check')?.checked;if(!db.notificationsEnabled){save();toast('Browser notifications disabled.');return}if(!('Notification'in window)){toast('Browser notifications are unavailable; website alerts remain enabled.','warn')}else{let p=Notification.permission;if(p==='default')p=await Notification.requestPermission();if(p==='granted')toast('This browser is registered for alerts.');else toast('Permission not granted. Website alerts remain enabled.','warn')}if(!db.devices.some(d=>d.name==='This browser'))db.devices.push({name:'This browser',at:timeNow()});save();render()}
function saveLimit(){let n=Number(document.getElementById('demandLimit')?.value);if(!n||n<1){toast('Enter a valid demand limit.','warn');return}let prev=db.limit;db.limit=n;if(demand()>n&&prev>=demand())addAlert('Peak Demand',`Factory demand ${demand().toFixed(1)} kW is above the ${n} kW allowed limit. Please check active machines.`,null,'critical');save();render();toast('Maximum demand limit updated.')}
function saveFactory(){db.factory=document.getElementById('factory-name').value.trim()||db.factory;db.location=document.getElementById('factory-location').value.trim();save();render();toast('Factory information saved.')}
function saveEnergy(){db.cost=Number(document.getElementById('energy-cost').value)||db.cost;db.limit=Number(document.getElementById('settings-limit').value)||db.limit;db.start=document.getElementById('factory-start').value||db.start;save();render();toast('Energy settings saved.')}
function setReportCode(){let c=document.getElementById('new-code').value;if(!/^\d{4}$/.test(c)){toast('Report code must contain exactly four digits.','warn');return}db.reportCode=c;save();render();toast('Owner report code updated.')}
function generateReport(){let code=document.getElementById('report-code').value;if(code!==db.reportCode){toast('That owner code is not correct.','error');return}db.reportGenerated=true;db.reports.unshift({date:dateNow(),time:timeNow()});save();render();setTimeout(()=>document.getElementById('report')?.scrollIntoView({behavior:'smooth',block:'start'}),100)}
function addMachine(){let name=prompt('Machine name (e.g. CNC Machine 03):');if(!name?.trim())return;let id=prompt('Machine ID:',`M${String(db.machines.length+1).padStart(3,'0')}`);if(!id?.trim())return;if(db.machines.some(m=>m.id.toLowerCase()===id.toLowerCase())){toast('That machine ID is already in use.','error');return}let type=prompt('Machine type:',name.split(' ')[0])||'Machine';db.machines.push({id:id.toUpperCase().trim(),name:name.trim(),type,power:4.5,normal:6,health:100,state:'Running',idle:false,last:timeNow()});save();render();toast(`${name} added.`)}
function setLangAndPage(v){setLang(v)}
// Local prototype authentication and protected-page gates.
translations.en.Explore='Create account';
function enterDemo(){showAuth('signup')}
function showAuth(mode='login'){authMode=mode;document.querySelector('.auth-overlay')?.remove();document.body.insertAdjacentHTML('beforeend',authModal())}
function closeAuth(){document.querySelector('.auth-overlay')?.remove()}
function authModal(){let signup=authMode==='signup';return `<div class="auth-overlay" onclick="if(event.target===this)closeAuth()"><div class="auth-card"><button class="close-btn" onclick="closeAuth()">×</button><div class="brand-mark">U</div><h2>${signup?'Create your factory account':'Sign in to UrjaDrishti'}</h2><p>${signup?'Set up a local prototype account for your factory.':'Sign in with the account created on this browser.'}</p>${signup?`<label class="form-label">Your name</label><input class="input" id="auth-name" placeholder="Factory owner or manager" autocomplete="name"><label class="form-label">Factory name</label><input class="input" id="auth-factory" placeholder="Your factory" value="${esc(db.factory)}">`:''}<label class="form-label">Email</label><input class="input" id="auth-email" type="email" placeholder="name@factory.com" autocomplete="username"><label class="form-label">Password</label><input class="input" id="auth-password" type="password" placeholder="${signup?'At least 8 characters':'Your password'}" autocomplete="${signup?'new-password':'current-password'}">${signup?`<label class="checkbox-line"><input type="checkbox" id="auth-register" checked> Register this browser for notifications</label>`:''}<button class="button full" style="margin-top:12px" onclick="submitAuth()">${signup?'Create account':'Sign in'}</button><div class="small" style="text-align:center;margin-top:13px">${signup?'Already have an account?':'New to UrjaDrishti?'} <button class="link-button" onclick="showAuth('${signup?'login':'signup'}')">${signup?'Sign in':'Create account'}</button></div><div class="small" style="margin-top:12px">Firebase verifies your sign-in. This prototype keeps factory demo readings in this browser.</div></div></div>`}
async function passwordDigest(password,salt){if(!crypto?.subtle||!crypto?.getRandomValues)throw Error('Secure browser cryptography is unavailable. Run the prototype on localhost or HTTPS.');let key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);let bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new Uint8Array(salt),iterations:120000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(bits),b=>b.toString(16).padStart(2,'0')).join('')}
async function submitAuth(){let email=document.getElementById('auth-email')?.value.trim().toLowerCase(),password=document.getElementById('auth-password')?.value;if(!email||!/^\S+@\S+\.\S+$/.test(email)){toast('Enter a valid email address.','warn');return}if(!password){toast('Enter your password.','warn');return}try{if(authMode==='signup'){if(password.length<8){toast('Use a password with at least 8 characters.','warn');return}if(db.account){toast('An account is already registered in this browser. Sign in instead.','warn');return}let name=document.getElementById('auth-name').value.trim()||'Factory Admin',factory=document.getElementById('auth-factory').value.trim()||db.factory,salt=crypto.getRandomValues(new Uint8Array(16));db.account={email,name,salt:Array.from(salt),hash:await passwordDigest(password,salt)};db.factory=factory;if(document.getElementById('auth-register')?.checked&&!db.devices.some(x=>x.name==='This browser'))db.devices.push({name:'This browser',at:timeNow()})}else{if(!db.account){toast('No account exists in this browser yet. Create an account first.','warn');return}if(email!==db.account.email||await passwordDigest(password,db.account.salt)!==db.account.hash){toast('Email or password is incorrect.','error');return}}db.user=db.account.name;db.loggedIn=true;save();closeAuth();view='overview';render();toast(`Welcome, ${db.account.name}.`)}catch(e){toast(e.message||'Could not complete sign-in.','error')}}
function logout(){db.loggedIn=false;save();view='landing';document.querySelector('.auth-overlay')?.remove();render();toast('You have signed out.')}
function go(v,authorized=false){if(!db.loggedIn){showAuth('login');return}if(!authorized&&(v==='settings'||v==='reports')){showAccessGate(v);return}view=v;render();window.scrollTo(0,0)}
function showAccessGate(route){pendingRoute=route;document.querySelector('.access-overlay')?.remove();let settings=route==='settings';let label=settings?'superior access code':'report access code';document.body.insertAdjacentHTML('beforeend',`<div class="auth-overlay access-overlay" onclick="if(event.target===this)closeAccessGate()"><form class="auth-card" onsubmit="event.preventDefault();verifyAccessCode()"><button type="button" class="close-btn" onclick="closeAccessGate()">×</button><div class="brand-mark">${settings?'⚙':'▤'}</div><h2>${settings?'Restricted settings':'Protected reports'}</h2><p>${settings?'Enter the code issued to an authorized superior to open factory settings.':'Enter the owner report code to open daily reports.'}</p><label class="form-label" for="access-code">${settings?'Superior':'Owner'} code</label><input class="input" id="access-code" type="password" inputmode="numeric" maxlength="8" autocomplete="off" autofocus><button class="button full" style="margin-top:14px">Unlock ${settings?'settings':'reports'}</button><div class="small" style="text-align:center;margin-top:12px">Access is checked each time this section is opened.</div></form></div>`);setTimeout(()=>document.getElementById('access-code')?.focus(),0)}
function closeAccessGate(){document.querySelector('.access-overlay')?.remove();pendingRoute=''}
function verifyAccessCode(){let input=document.getElementById('access-code')?.value,route=pendingRoute,expected=route==='settings'?db.superiorCode:db.reportCode;if(input!==expected){toast('That access code is incorrect.','error');return}document.querySelector('.access-overlay')?.remove();pendingRoute='';go(route,true)}
function settingsPage(){return `${pageHead('Settings','Restricted factory configuration. Changes here apply to this browser prototype.')}<div class="settings-grid"><article class="card settings-card"><h2>Factory information</h2><p>This account represents one factory.</p><div class="field-row"><div><label class="form-label">Factory name</label><input id="factory-name" class="input" value="${esc(db.factory)}"></div><div><label class="form-label">Location</label><input id="factory-location" class="input" value="${esc(db.location)}"></div></div><button class="button" style="margin-top:13px" onclick="saveFactory()">Save factory</button></article><article class="card settings-card"><h2>Energy configuration</h2><p>Values used for meter summaries and demand checks.</p><div class="field-row"><div><label class="form-label">Electricity cost (₹ / kWh)</label><input id="energy-cost" class="input" type="number" value="${db.cost}"></div><div><label class="form-label">Maximum demand (kW)</label><input id="settings-limit" class="input" type="number" value="${db.limit}"></div></div><label class="form-label">Factory start time</label><input id="factory-start" class="input" type="time" value="${db.start}"><button class="button" style="margin-top:13px" onclick="saveEnergy()">Save energy settings</button></article><article class="card settings-card"><h2>Machines</h2><p>${db.machines.length} configurable machine records.</p><button class="button secondary" onclick="addMachine()">＋ Add a machine</button><div style="margin-top:14px">${db.machines.slice(0,4).map(m=>`<div class="list-row"><span>${esc(m.name)} <span class="small">${m.id}</span></span><strong>${m.normal.toFixed(1)} kW baseline</strong></div>`).join('')}</div></article><article class="card settings-card"><h2>Notifications</h2><p>Website notification center remains available as a fallback.</p><label class="checkbox-line"><input type="checkbox" id="push-check" ${db.notificationsEnabled?'checked':''}> Enable browser notifications on this device</label><button class="button secondary" onclick="registerNotifications()">Register this device</button><div class="small" style="margin-top:10px">Registered devices: ${db.devices.length}</div></article><article class="card settings-card"><h2>Owner and superior access codes</h2><p>Use distinct codes. Share the superior code only with authorized factory officials.</p><label class="form-label">Change superior settings code</label><input id="new-superior-code" class="input" type="password" inputmode="numeric" maxlength="8" placeholder="At least 4 digits"><button class="button secondary" style="margin-top:10px" onclick="setSuperiorCode()">Update superior code</button><label class="form-label">Change report access code</label><input id="new-code" class="input" type="password" inputmode="numeric" maxlength="8" placeholder="At least 4 digits"><button class="button secondary" style="margin-top:10px" onclick="setReportCode()">Update report code</button><div class="small" style="margin-top:10px">Initial demo codes: Settings 7314 · Reports 2468. Change these after setup.</div></article><article class="card settings-card"><h2>Language</h2><p>Navigation and key labels support Indian languages.</p><select class="select" onchange="setLang(this.value)"><option value="en" ${db.language==='en'?'selected':''}>English</option><option value="hi" ${db.language==='hi'?'selected':''}>Hindi</option><option value="pa" ${db.language==='pa'?'selected':''}>Punjabi</option><option value="mr" ${db.language==='mr'?'selected':''}>Marathi</option><option value="ta" ${db.language==='ta'?'selected':''}>Tamil</option></select><div class="section"><button class="button secondary" onclick="logout()">Sign out</button></div></article></div><div class="device-note section"><strong>Prototype security note:</strong> Codes and account data are stored in this browser. They deter casual access but are not a substitute for server-side roles and authentication.</div>`}
function setSuperiorCode(){let c=document.getElementById('new-superior-code')?.value;if(!/^\d{4,8}$/.test(c||'')){toast('Use a superior code with 4–8 digits.','warn');return}db.superiorCode=c;save();render();toast('Superior settings code updated.')}
function setReportCode(){let c=document.getElementById('new-code')?.value;if(!/^\d{4,8}$/.test(c||'')){toast('Use a report access code with 4–8 digits.','warn');return}db.reportCode=c;save();render();toast('Report access code updated.')}
function reportsPage(){let c=healthCounts(),d=demand();return `${pageHead('Daily Reports','Owner access verified. Prepare and print today’s factory summary.',`<button class="button" onclick="generateReport()">▤ &nbsp; Generate report</button>`)}${db.reportGenerated?`<div class="report-preview" id="report"><div class="report-head"><div><div class="report-logo">◉ UrjaDrishti</div><div class="small">Daily Factory Monitoring Report</div></div><div style="text-align:right;font-size:10px"><strong>${esc(db.factory)}</strong><div class="small">${dateNow()} · Generated ${timeNow()}</div></div></div><div class="report-kpis"><div><small>Total energy today</small><strong>1,248 kWh</strong></div><div><small>Peak demand</small><strong>${d.toFixed(1)} kW</strong></div><div><small>Machines monitored</small><strong>${db.machines.length}</strong></div></div><h3 style="font:700 13px Manrope">Machine status summary</h3><div class="list-row"><span>Healthy</span><strong>${c.healthy}</strong></div><div class="list-row"><span>Attention</span><strong>${c.attention}</strong></div><div class="list-row"><span>Possible fault</span><strong>${c.fault}</strong></div><div class="section"><h3 style="font:700 13px Manrope">Machine readings</h3><div class="table-wrap"><table class="machine-table"><thead><tr><th>MACHINE</th><th>STATUS</th><th>POWER</th><th>HEALTH</th></tr></thead><tbody>${db.machines.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.state)}</td><td>${m.power.toFixed(1)} kW</td><td>${m.health}</td></tr>`).join('')}</tbody></table></div></div><div class="section"><h3 style="font:700 13px Manrope">Alerts today</h3>${alertList(db.alerts)}</div><p class="small" style="margin-top:20px">Prototype report · Based on simulated meter readings and stored demo checks. Not an industrial assessment.</p></div><div class="pill-row" style="justify-content:center;margin-top:12px"><button class="button" onclick="window.print()">Print / Save as PDF</button></div>`:`<div class="workflow"><div class="card workflow-card"><div class="record-box"><div class="record-orb">▤</div><h3>Today's report is ready to generate</h3><p>The report uses this factory’s stored daily readings, machine statuses, and alerts.</p><button class="button" onclick="generateReport()">Generate report</button></div></div></div>`}`}
function generateReport(){db.reportGenerated=true;db.reports.unshift({date:dateNow(),time:timeNow()});save();render();setTimeout(()=>document.getElementById('report')?.scrollIntoView({behavior:'smooth',block:'start'}),100)}
