uiLocales.kn=Object.fromEntries(uiKeys.map((k,i)=>[k,['ಊರ್ಜಾದೃಷ್ಟಿ','ಕಾರ್ಖಾನೆ ಬುದ್ಧಿವಂತಿಕೆ','ಕಾರ್ಯಸ್ಥಳ','ನಿಮ್ಮ ಕಾರ್ಖಾನೆ','ಕಾರ್ಖಾನೆ ನಿರ್ವಾಹಕ','ಮಾಲೀಕರ ಖಾತೆ','ಅವಲೋಕನ','ಯಂತ್ರಗಳು','ಮೇಲ್ವಿಚಾರಣೆ','ಎಚ್ಚರಿಕೆಗಳು','ವರದಿಗಳು','ಸೆಟ್ಟಿಂಗ್‌ಗಳು','ಯಂತ್ರ ಆರೋಗ್ಯ','ಗಾಳಿ ಸೋರಿಕೆ ಪತ್ತೆ','ನಿಷ್ಕ್ರಿಯ ಮೇಲ್ವಿಚಾರಣೆ','ಗರಿಷ್ಠ ಬೇಡಿಕೆ','ಪ್ರಸ್ತುತ ಬೇಡಿಕೆ','ಇಂದಿನ ಶಕ್ತಿ','ಸಕ್ರಿಯ ಎಚ್ಚರಿಕೆಗಳು','ಆರೋಗ್ಯಕರ','ಗಮನಿಸಿ','ಸಂಭಾವ್ಯ ದೋಷ','ಚಾಲನೆಯಲ್ಲಿದೆ','ನಿಷ್ಕ್ರಿಯ','ಸಾಮಾನ್ಯ','ಮಿತಿ ಮೀರಿದೆ','ಸಂಪರ್ಕಗೊಂಡಿದೆ','ಯಂತ್ರ ಅವಲೋಕನ','ನೇರ ಓದುಗಳು · ಪ್ರತಿ 10 ನಿಮಿಷಕ್ಕೆ ನವೀಕರಣ','ಸ್ಥಿತಿ','ವಿದ್ಯುತ್','ಆರೋಗ್ಯ','ಕೊನೆಯ ಪರಿಶೀಲನೆ','ಸಕ್ರಿಯ ಎಚ್ಚರಿಕೆಗಳಿಲ್ಲ','ಎಲ್ಲವೂ ಸರಿಯಾಗಿದೆ','ಇನ್ನೂ ಎಚ್ಚರಿಕೆಗಳಿಲ್ಲ','ಪರಿಹರಿಸಿ','ಎಲ್ಲವನ್ನೂ ಓದಿದಂತೆ ಗುರುತಿಸಿ'][i]||k]));
function localizeNode(node){let lang=db.language,map=uiLocales[lang];if(!map)return;let raw=node.nodeValue,lead=raw.match(/^\s*/)?.[0]||'',tail=raw.match(/\s*$/)?.[0]||'',s=raw.trim();if(!s)return;for(const key of Object.keys(map).sort((a,b)=>b.length-a.length)){if(map[key]&&map[key]!==key)s=s.split(key).join(map[key])}node.nodeValue=lead+s+tail}
function localizeRendered(root=document.getElementById('app')){if(!root)return;root.querySelectorAll('option[value="gu"],option[value="bn"],option[value="kn"]').forEach(el=>el.remove());if(db.language==='en')return;let walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode()){let n=walker.currentNode;if(!n.parentElement?.closest('.machine-name,.machine-id,.factory-switch strong,.report-head strong,.page-head .eyebrow')&&!(view==='machine'&&n.parentElement?.closest('.page-head h1')))localizeNode(n)}root.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>{for(const attr of ['placeholder','aria-label','title'])if(el.hasAttribute(attr)){let holder=document.createTextNode(el.getAttribute(attr));localizeNode(holder);el.setAttribute(attr,holder.nodeValue)}});document.documentElement.lang=db.language;document.title=(uiLocales[db.language]?.UrjaDrishti||'UrjaDrishti')+' — '+(uiLocales[db.language]?.['Factory monitoring overview']||'Factory monitoring')}
function render(){let app=document.getElementById('app');if(!db.loggedIn){app.innerHTML=landing();localizeRendered(app);return}let body=({overview:dashboard,machines:machinesPage,monitor:monitorPage,health:workflowPage,leak:workflowPage,idle:idlePage,demand:demandPage,alerts:alertsPage,reports:reportsPage,settings:settingsPage,machine:machineDetail})[view]?.()||dashboard();app.innerHTML=shell(body);mountSignalUploader(app);localizeRendered(app)}
function setLang(v){db.language=v;save();render();document.querySelectorAll('.auth-overlay,.access-overlay').forEach(localizeRendered)}
function toast(msg,type=''){let el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;localizeRendered(el);document.getElementById('toast-region').append(el);setTimeout(()=>el.remove(),3400)}
function showAuth(mode='login'){authMode=mode;document.querySelector('.auth-overlay')?.remove();document.body.insertAdjacentHTML('beforeend',authModal());localizeRendered(document.querySelector('.auth-overlay'))}
function showAccessGate(route){pendingRoute=route;document.querySelector('.access-overlay')?.remove();let settings=route==='settings';document.body.insertAdjacentHTML('beforeend',`<div class="auth-overlay access-overlay" onclick="if(event.target===this)closeAccessGate()"><form class="auth-card" onsubmit="event.preventDefault();verifyAccessCode()"><button type="button" class="close-btn" onclick="closeAccessGate()">×</button><div class="brand-mark">${settings?'⚙':'▤'}</div><h2>${settings?'Restricted settings':'Protected reports'}</h2><p>${settings?'Enter the code issued to an authorized superior to open factory settings.':'Enter the owner report code to open daily reports.'}</p><label class="form-label" for="access-code">${settings?'Superior':'Owner'} code</label><input class="input" id="access-code" type="password" inputmode="numeric" maxlength="8" autocomplete="off" autofocus><button class="button full" style="margin-top:14px">Unlock ${settings?'settings':'reports'}</button><div class="small" style="text-align:center;margin-top:12px">Access is checked each time this section is opened.</div></form></div>`);localizeRendered(document.querySelector('.access-overlay'));setTimeout(()=>document.getElementById('access-code')?.focus(),0)}
function setAuthDocumentLanguage(){document.documentElement.lang=db.language}
window.urjaAuthMode=()=>authMode;
window.urjaToast=toast;
function submitAuth(){toast('Firebase Authentication is loading. Please try again in a moment.','warn')}
function login(){toast('Use the Firebase sign-in form to continue.','warn')}
window.urjaSetFactory=name=>{db.factory=name;save()};
window.urjaRegisterThisDevice=()=>{if(!db.devices.some(d=>d.name==='This browser'))db.devices.push({name:'This browser',at:timeNow()});save()};
window.urjaSetSession=user=>{const nextUid=user?.uid||null;if(nextUid!==firebaseUid){firebaseUid=nextUid;if(user){db=loadForUser(nextUid);if(!['en','hi','pa','mr','ta'].includes(db.language))db.language='en'}}db.loggedIn=!!user;db.user=user?.displayName||user?.email?.split('@')[0]||'Factory Admin';if(user)save();view=user?'overview':'landing';document.querySelector('.auth-overlay')?.remove();render()};
window.closeAuth=closeAuth;
// Simulated meter check: real dashboard values change only on the 10-minute cadence.
function meterCheck(){let now=Date.now();if(now-db.lastMeterCheck<600000)return;db.lastMeterCheck=now;db.machines.forEach(m=>{m.power=Math.max(.4,Math.round((m.power+(Math.random()-.5)*.8)*10)/10);m.last=timeNow();if(m.power<(m.threshold||3)){m.idleMinutes=(m.idleMinutes||0)+10;if(m.idleMinutes>=10&&!m.idle){m.idle=true;m.state='Idle'}if(m.idleMinutes>=10)addAlert('Idle',`${m.name} is below normal operating power (${m.power.toFixed(1)} kW vs ${m.normal.toFixed(1)} kW). Check ${m.name}.`,m.id,'warning')}else{m.idleMinutes=0;m.idle=false;if(m.state==='Idle')m.state='Running'}});if(demand()>db.limit)addAlert('Peak Demand',`Factory demand ${demand().toFixed(1)} kW is above the ${db.limit} kW allowed limit. Please check active machines.`,null,'critical');save();if(db.loggedIn)render()}
document.addEventListener('change',e=>{if(e.target?.id==='machine-select'&&e.target.value==='custom'){document.getElementById('custom-location').innerHTML='<label class="form-label">Location name</label><input id="custom-name" class="input" placeholder="e.g. Air line near bay 2">'}});


function useUploadedSignal(stage,input){const file=input.files?.[0];if(!file)return;const ext=file.name.split('.').pop().toLowerCase();const leak=workflow.kind==='leak';const valid=stage==='audio'?(leak?ext==='wav':['wav','csv'].includes(ext)):ext==='csv';if(!valid){toast(leak?'Choose a valve WAV file.':stage==='audio'?'Choose a WAV or MAFAULDA CSV file.':'Choose a vibration CSV file.','error');input.value='';return}if(file.size>64*1024*1024){toast('Uploads must be 64 MB or smaller.','error');input.value='';return}workflow[stage+'File']=file;workflow[stage+'Done']=true;if(stage==='audio'){workflow.audio=null;workflow.audioBlob=null}else workflow.vibration=null;render()}
function mountSignalUploader(app){if(!['health','leak'].includes(view)||workflow.step!==1||workflow.recording)return;const stage=workflow.recordingStage||'audio',vibration=stage==='vibration',leak=workflow.kind==='leak',actions=app.querySelector('.record-box .record-actions');if(!actions)return;const label=document.createElement('label');label.className='upload-action';const title=document.createElement('span');title.textContent='Or upload '+(leak?'valve audio WAV':vibration?'vibration CSV':'machine audio file');const input=document.createElement('input');input.type='file';input.accept=leak?'.wav,audio/wav':vibration?'.csv,text/csv':'.wav,.csv,audio/wav,text/csv';input.addEventListener('change',()=>useUploadedSignal(stage,input));const note=document.createElement('small');note.textContent=leak?'Valve audio: WAV file, preferably the same 16 kHz, 8-channel format as the MIMII training recordings.':'Audio: WAV or 8-column MAFAULDA CSV, headerless, 50 kHz microphone channel.';label.append(title,input,note);actions.append(label);const result=app.querySelector('.record-result');const file=workflow[stage+'File'];if(result&&file)result.textContent=(leak?'Valve audio':vibration?'Vibration':'Audio')+' file selected: '+file.name+' · ready for model preprocessing'}

render();setInterval(meterCheck,15000);
